# Dump every hologram material instance's parameter values (textures, vectors, scalars) to the log.
import unreal
MEL = unreal.MaterialEditingLibrary
EAL = unreal.EditorAssetLibrary
for path in sorted(EAL.list_assets("/Game/HologramShader/Materials", recursive=True)):
    a = EAL.load_asset(path)
    if isinstance(a, unreal.MaterialInstanceConstant):
        parts = []
        for n in MEL.get_texture_parameter_names(a):
            t = MEL.get_material_instance_texture_parameter_value(a, n)
            parts.append("%s=%s" % (n, t.get_name() if t else None))
        for n in MEL.get_vector_parameter_names(a):
            c = MEL.get_material_instance_vector_parameter_value(a, n)
            parts.append("%s=(%.2f,%.2f,%.2f)" % (n, c.r, c.g, c.b))
        for n in MEL.get_scalar_parameter_names(a):
            parts.append("%s=%.2f" % (n, MEL.get_material_instance_scalar_parameter_value(a, n)))
        unreal.log("HOLO %s | %s" % (a.get_name(), " ".join(parts)))
    elif isinstance(a, unreal.Material):
        unreal.log("HOLO MASTER %s blend=%s" % (a.get_name(), a.get_editor_property("blend_mode")))
# Which spheres in the demo map use which instance, and where (to tell the owner's pictures apart).
world = unreal.EditorLoadingAndSavingUtils.load_map("/Game/HologramShader/Maps/Hologram")
for actor in unreal.EditorLevelLibrary.get_all_level_actors():
    for comp in actor.get_components_by_class(unreal.StaticMeshComponent):
        mats = [m.get_name() for m in comp.get_materials() if m]
        if any("Hologram" in m for m in mats):
            loc = actor.get_actor_location()
            unreal.log("HOLO MAP %s at (%.0f, %.0f, %.0f) mats=%s" % (actor.get_actor_label(), loc.x, loc.y, loc.z, mats))
    if isinstance(actor, unreal.TextRenderActor):
        loc = actor.get_actor_location()
        unreal.log("HOLO TEXT '%s' at (%.0f, %.0f, %.0f)" % (actor.text_render.get_editor_property("text"), loc.x, loc.y, loc.z))

