# Dump M_Hologram's settings and the expression types it uses (UV source, WPO, time), and which outputs are wired.
import unreal
MEL = unreal.MaterialEditingLibrary
m = unreal.load_asset("/Game/HologramShader/Materials/HologramShader/M_Hologram")
for p in ("blend_mode", "shading_model", "two_sided", "translucency_lighting_mode", "used_with_static_lighting"):
    try:
        unreal.log("INSPECT %s = %s" % (p, m.get_editor_property(p)))
    except Exception as e:
        unreal.log("INSPECT %s ? %s" % (p, e))
P = unreal.MaterialProperty
for prop in ("MP_BASE_COLOR", "MP_EMISSIVE_COLOR", "MP_OPACITY", "MP_OPACITY_MASK", "MP_NORMAL", "MP_WORLD_POSITION_OFFSET", "MP_REFRACTION"):
    node = MEL.get_material_property_input_node(m, getattr(P, prop))
    unreal.log("INSPECT input %s <- %s" % (prop, node.get_class().get_name() if node else None))
counts = {}
for e in MEL.get_material_expressions(m) if hasattr(MEL, "get_material_expressions") else []:
    n = e.get_class().get_name()
    counts[n] = counts.get(n, 0) + 1
    if n == "MaterialExpressionTextureCoordinate":
        unreal.log("INSPECT texcoord index=%s" % e.get_editor_property("coordinate_index"))
unreal.log("INSPECT nodes %s" % sorted(counts.items()))
unreal.log("INSPECT num expressions %s" % MEL.get_num_material_expressions(m))

